          if (els.daysActive) {
            const startDate = log.length > 0 ? new Date(log[0].runAt) : new Date("2026-10-04T00:00:00Z");
            const daysActive = Math.floor((now.getTime() - startDate.getTime()) / (24 * 60 * 60 * 1000)) + 1;
            els.daysActive.textContent = daysActive;
